const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaBrain, FaRegLightbulb, FaTools, FaCheckCircle, FaExclamationTriangle, FaChartBar, FaBookOpen } = require("react-icons/fa");

async function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = await renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

(async () => {
  let pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9'; // 10" x 5.625"
  pres.author = 'AI Agent';
  pres.title = 'KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge';

  const COLORS = {
    darkBg: "1E293B",
    darkAccent: "0F172A",
    lightBg: "F8FAFC",
    primary: "0EA5E9", // sky-500
    secondary: "0284C7", // sky-600
    accent: "38BDF8", // sky-400
    teal: "0D9488",
    tealLight: "14B8A6",
    textDark: "0F172A",
    textLight: "F8FAFC",
    textMuted: "64748B",
    textMutedLight: "94A3B8",
    error: "EF4444",
    success: "10B981"
  };

  // Generate some icons
  const iconBrain = await iconToBase64Png(FaBrain, "#" + COLORS.primary);
  const iconLightbulb = await iconToBase64Png(FaRegLightbulb, "#" + COLORS.teal);
  const iconTools = await iconToBase64Png(FaTools, "#" + COLORS.error);
  const iconCheck = await iconToBase64Png(FaCheckCircle, "#" + COLORS.success);
  const iconCheckDark = await iconToBase64Png(FaCheckCircle, "#" + COLORS.tealLight);
  const iconWarn = await iconToBase64Png(FaExclamationTriangle, "#" + COLORS.error);
  const iconBook = await iconToBase64Png(FaBookOpen, "#" + COLORS.primary);

  // Master Slide Definition
  pres.defineSlideMaster({
    title: 'TITLE_SLIDE',
    background: { color: COLORS.darkBg },
    objects: [
      { rect: { x: 0, y: 5.125, w: 10, h: 0.5, fill: { color: COLORS.darkAccent } } }
    ]
  });

  pres.defineSlideMaster({
    title: 'CONTENT_SLIDE',
    background: { color: COLORS.lightBg },
    objects: [
      { rect: { x: 0, y: 5.125, w: 10, h: 0.5, fill: { color: "FFFFFF" } } },
      { text: { text: "KnowSelf: Agentic Knowledgeable Self-Awareness", options: { x: 0.5, y: 5.25, w: 9, h: 0.25, color: COLORS.textMuted, fontSize: 10, fontFace: "Calibri" } } }
    ]
  });

  // SLIDE 1: Title (Dark)
  let slide1 = pres.addSlide({ masterName: "TITLE_SLIDE" });

  // Decorative circle
  slide1.addShape(pres.shapes.OVAL, { x: -2, y: -2, w: 6, h: 6, fill: { color: COLORS.primary, transparency: 85 } });

  slide1.addText("KnowSelf", {
    x: 0.5, y: 1.2, w: 9, h: 0.8,
    fontSize: 44, fontFace: "Georgia", color: COLORS.primary, bold: true, margin: 0
  });

  slide1.addText("Agentic Knowledgeable Self-Awareness for LLM-Based Agents", {
    x: 0.5, y: 2.1, w: 9, h: 0.5,
    fontSize: 24, fontFace: "Georgia", color: COLORS.textLight, margin: 0
  });

  slide1.addText("Teaching LLM Agents When to Think, Reflect, or Seek Knowledge", {
    x: 0.5, y: 2.8, w: 9, h: 0.5,
    fontSize: 18, fontFace: "Calibri", color: COLORS.textMutedLight, margin: 0, italic: true
  });

  slide1.addText("Enabling agents to autonomously regulate knowledge utilization through situational self-awareness.", {
    x: 0.5, y: 3.8, w: 9, h: 0.5,
    fontSize: 14, fontFace: "Calibri", color: COLORS.textLight, margin: 0
  });

  slide1.addText("Source: arxiv.org/abs/2504.03553", {
    x: 0.5, y: 4.4, w: 9, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: COLORS.textMutedLight, margin: 0
  });

  // SLIDE 2: Problem - Flood Irrigation (Light)
  let slide2 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
  slide2.addText("Current Agent Training Uses 'Flood Irrigation'", {
    x: 0.5, y: 0.3, w: 9, h: 0.5, fontSize: 32, fontFace: "Georgia", color: COLORS.textDark, bold: true, margin: 0
  });
  slide2.addText("Indiscriminate Knowledge Injection Hurts Efficiency", {
    x: 0.5, y: 0.9, w: 9, h: 0.3, fontSize: 18, fontFace: "Calibri", color: COLORS.secondary, margin: 0, bold: true
  });

  slide2.addText("Current agent learning resembles unconscious pattern-fitting rather than situational awareness. They blindly inject knowledge regardless of whether the agent needs it at a given step.", {
    x: 0.5, y: 1.4, w: 9, h: 0.6, fontSize: 14, fontFace: "Calibri", color: COLORS.textDark, margin: 0
  });

  // 3 Boxes for existing paradigms
  const boxY = 2.2;
  const boxW = 2.8;
  const boxH = 1.8;
  const spacing = 0.3;
  const startX = 0.5;

  // Box 1
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: startX, y: boxY, w: boxW, h: boxH, fill: { color: "FFFFFF" }, line: { color: COLORS.error, width: 2 },
    shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
